// Package logparse parses nginx "combined" access log lines that end with the
// request time in seconds.
package logparse

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"
	"time"
)

// TimeLayout is the layout of the bracketed timestamp field.
const TimeLayout = "02/Jan/2006:15:04:05 -0700"

// MaxLineBytes is the longest line that is parsed. Longer lines are counted
// as malformed.
const MaxLineBytes = 1 << 20

// Entry is one parsed access log record.
type Entry struct {
	RemoteAddr  string
	Time        time.Time
	Method      string
	Target      string // request target as sent, with query string
	Path        string // request target without query string
	Proto       string
	Status      int
	Bytes       int64 // -1 when the log has "-"
	Referer     string
	UserAgent   string
	RequestTime time.Duration
}

// Parse parses a single log line. Errors wrap ErrMalformed.
func Parse(line string) (Entry, error) {
	var e Entry
	rest := strings.TrimSpace(line)
	var f [10]string
	for i := range f {
		var err error
		f[i], rest, err = nextField(rest)
		if err != nil {
			return Entry{}, fmt.Errorf("field %d: %w: %v", i+1, ErrMalformed, err)
		}
	}
	if strings.TrimSpace(rest) != "" {
		return Entry{}, fmt.Errorf("trailing data after request time: %w", ErrMalformed)
	}

	e.RemoteAddr = f[0]
	// f[1] is the ident and f[2] the user; neither is used.

	t, err := time.Parse(TimeLayout, f[3])
	if err != nil {
		return Entry{}, fmt.Errorf("time %q: %w", f[3], ErrMalformed)
	}
	e.Time = t

	parts := strings.Split(f[4], " ")
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
		return Entry{}, fmt.Errorf("request %q: %w", f[4], ErrMalformed)
	}
	e.Method, e.Target, e.Proto = parts[0], parts[1], parts[2]
	e.Path = e.Target
	if i := strings.IndexByte(e.Path, '?'); i >= 0 {
		e.Path = e.Path[:i]
	}
	if e.Path == "" {
		return Entry{}, fmt.Errorf("request %q has empty path: %w", f[4], ErrMalformed)
	}

	e.Status, err = strconv.Atoi(f[5])
	if err != nil || e.Status < 100 || e.Status > 599 {
		return Entry{}, fmt.Errorf("status %q: %w", f[5], ErrMalformed)
	}

	if f[6] == "-" {
		e.Bytes = -1
	} else {
		e.Bytes, err = strconv.ParseInt(f[6], 10, 64)
		if err != nil || e.Bytes < 0 {
			return Entry{}, fmt.Errorf("bytes %q: %w", f[6], ErrMalformed)
		}
	}

	e.Referer, e.UserAgent = f[7], f[8]

	secs, err := strconv.ParseFloat(f[9], 64)
	if err != nil || math.IsNaN(secs) || math.IsInf(secs, 0) || secs < 0 || secs > 1e9 {
		return Entry{}, fmt.Errorf("request time %q: %w", f[9], ErrMalformed)
	}
	e.RequestTime = time.Duration(math.Round(secs * float64(time.Second)))
	return e, nil
}

// nextField returns the next whitespace-separated field of s. A field that
// starts with '[' runs to the closing ']' and one that starts with '"' runs
// to the closing unescaped '"'; the delimiters are removed.
func nextField(s string) (field, rest string, err error) {
	s = strings.TrimLeft(s, " \t")
	if s == "" {
		return "", "", fmt.Errorf("missing field")
	}
	switch s[0] {
	case '[':
		i := strings.IndexByte(s, ']')
		if i < 0 {
			return "", "", fmt.Errorf("unterminated '['")
		}
		return s[1:i], s[i+1:], nil
	case '"':
		for i := 1; i < len(s); i++ {
			switch s[i] {
			case '\\':
				i++
			case '"':
				return s[1:i], s[i+1:], nil
			}
		}
		return "", "", fmt.Errorf("unterminated quote")
	}
	i := strings.IndexAny(s, " \t")
	if i < 0 {
		return s, "", nil
	}
	return s[:i], s[i:], nil
}

// Scan reads r line by line and calls fn for every valid entry. Blank lines
// are ignored. It returns the number of malformed lines, which are skipped.
// It stops early with the context's error when ctx is cancelled, and with the
// error from r if reading fails.
func Scan(ctx context.Context, r io.Reader, fn func(Entry)) (malformed int, err error) {
	br := bufio.NewReaderSize(r, 64*1024)
	var buf []byte
	tooLong := false
	for {
		if err := ctx.Err(); err != nil {
			return malformed, fmt.Errorf("scan log: %w", err)
		}
		chunk, isPrefix, rerr := br.ReadLine()
		if rerr != nil {
			if rerr == io.EOF {
				return malformed, nil
			}
			return malformed, fmt.Errorf("read log: %w", rerr)
		}
		if !tooLong {
			if len(buf)+len(chunk) > MaxLineBytes {
				tooLong = true
				buf = buf[:0]
			} else {
				buf = append(buf, chunk...)
			}
		}
		if isPrefix {
			continue
		}
		switch {
		case tooLong:
			malformed++
		case strings.TrimSpace(string(buf)) == "":
		default:
			e, perr := Parse(string(buf))
			if perr != nil {
				malformed++
			} else {
				fn(e)
			}
		}
		buf = buf[:0]
		tooLong = false
	}
}

