func nextField(s string) (field, rest string, err error) {
	s = strings.TrimLeft(s, " \t")
	if s == "" {
		return "", "", fmt.Errorf("missing field")
	}
	switch s[0] {
	case '[':
		i := strings.IndexByte(s, ']')
		if i < 0 {
			return "", "", fmt.Errorf("unterminated '['")
		}
		return s[1:i], s[i+1:], nil
	case '"':
		for i := 1; i < len(s); i++ {
			switch s[i] {
			case '\\':
				i++
			case '"':
				return s[1:i], s[i+1:], nil
			}
		}
		return "", "", fmt.Errorf("unterminated quote")
	}
	i := strings.IndexAny(s, " \t")
	if i < 0 {
		return s, "", nil
	}
	return s[:i], s[i:], nil
}

// Scan reads r line by line and calls fn for every valid entry. Blank lines
// are ignored. It returns the number of malformed lines, which are skipped.
// It stops early with the context's error when ctx is cancelled, and with the
// error from r if reading fails.
func Scan(ctx context.Context, r io.Reader, fn func(Entry)) (malformed int, err error) {
	br := bufio.NewReaderSize(r, 64*1024)
	var buf []byte
	tooLong := false
	for {
		if err := ctx.Err(); err != nil {
			return malformed, fmt.Errorf("scan log: %w", err)
		}
		chunk, isPrefix, rerr := br.ReadLine()
		if rerr != nil {
			if rerr == io.EOF {
				return malformed, nil
			}
			return malformed, fmt.Errorf("read log: %w", rerr)
		}
		if !tooLong {
			if len(buf)+len(chunk) > MaxLineBytes {
				tooLong = true
				buf = buf[:0]
			} else {
				buf = append(buf, chunk...)
			}
		}
		if isPrefix {
			continue
		}
		switch {
		case tooLong:
			malformed++
		case strings.TrimSpace(string(buf)) == "":
		default:
			e, perr := Parse(string(buf))
			if perr != nil {
				malformed++
			} else {
				fn(e)
			}
		}
		buf = buf[:0]
		tooLong = false
	}
}

