package logparse

import (
	"context"
	"errors"
	"strings"
	"testing"
	"time"
)

const goodLine = `203.0.113.9 - - [10/Oct/2026:13:55:36 +0000] "GET /api/items?id=3 HTTP/1.1" 200 512 "-" "curl/8.0" 0.042`

func TestParse(t *testing.T) {
	tests := []struct {
		name    string
		line    string
		want    Entry
		wantErr bool
	}{
		{
			name: "good line",
			line: goodLine,
			want: Entry{
				RemoteAddr: "203.0.113.9", Method: "GET", Target: "/api/items?id=3",
				Path: "/api/items", Proto: "HTTP/1.1", Status: 200, Bytes: 512,
				Referer: "-", UserAgent: "curl/8.0", RequestTime: 42 * time.Millisecond,
			},
		},
		{
			name: "no query and dash bytes",
			line: `10.0.0.1 - bob [01/Jan/2026:00:00:00 +0100] "POST /x HTTP/2.0" 304 - "http://r/" "UA with spaces and \"quote\"" 1`,
			want: Entry{
				RemoteAddr: "10.0.0.1", Method: "POST", Target: "/x", Path: "/x",
				Proto: "HTTP/2.0", Status: 304, Bytes: -1, Referer: "http://r/",
				UserAgent: `UA with spaces and \"quote\"`, RequestTime: time.Second,
			},
		},
		{
			name: "query on root",
			line: `1.1.1.1 - - [01/Jan/2026:00:00:00 +0000] "GET /?a=b?c HTTP/1.1" 200 0 "-" "-" 0.000`,
			want: Entry{
				RemoteAddr: "1.1.1.1", Method: "GET", Target: "/?a=b?c", Path: "/",
				Proto: "HTTP/1.1", Status: 200, Referer: "-", UserAgent: "-",
			},
		},
		{name: "empty", line: "", wantErr: true},
		{name: "garbage", line: "hello world", wantErr: true},
		{name: "missing request time", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 5 "-" "ua"`, wantErr: true},
		{name: "plain combined without time", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 5 "-" "ua" x`, wantErr: true},
		{name: "bad timestamp", line: `1.1.1.1 - - [10/Foo/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 5 "-" "ua" 0.1`, wantErr: true},
		{name: "unterminated bracket", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000 "GET / HTTP/1.1" 200 5 "-" "ua" 0.1`, wantErr: true},
		{name: "unterminated quote", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1 200 5 "-" "ua" 0.1`, wantErr: true},
		{name: "request not three parts", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "-" 400 0 "-" "-" 0.001`, wantErr: true},
		{name: "empty path", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET ?a=b HTTP/1.1" 200 5 "-" "ua" 0.1`, wantErr: true},
		{name: "status not a number", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" OK 5 "-" "ua" 0.1`, wantErr: true},
		{name: "status out of range", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 999 5 "-" "ua" 0.1`, wantErr: true},
		{name: "negative bytes", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 -5 "-" "ua" 0.1`, wantErr: true},
		{name: "negative time", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 5 "-" "ua" -0.1`, wantErr: true},
		{name: "NaN time", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 5 "-" "ua" NaN`, wantErr: true},
		{name: "Inf time", line: `1.1.1.1 - - [10/Oct/2026:13:55:36 +0000] "GET / HTTP/1.1" 200 5 "-" "ua" Inf`, wantErr: true},
		{name: "trailing data", line: goodLine + " extra", wantErr: true},
	}
	for _, tc := range tests {
