			got, err := Parse(tc.line)
			if tc.wantErr {
				if !errors.Is(err, ErrMalformed) {
					t.Fatalf("Parse(%q) error = %v, want ErrMalformed", tc.line, err)
				}
				return
			}
			if err != nil {
				t.Fatalf("Parse(%q) error = %v, want nil", tc.line, err)
			}
			got.Time = time.Time{} // checked separately
			if got != tc.want {
				t.Errorf("Parse(%q) = %+v, want %+v", tc.line, got, tc.want)
			}
		})
	}
}

func TestParseTime(t *testing.T) {
	e, err := Parse(`1.1.1.1 - - [10/Oct/2026:13:55:36 +0200] "GET / HTTP/1.1" 200 5 "-" "ua" 0.1`)
	if err != nil {
		t.Fatalf("Parse error = %v", err)
	}
	want := time.Date(2026, 10, 10, 11, 55, 36, 0, time.UTC)
	if !e.Time.Equal(want) {
		t.Errorf("Parse time = %v, want %v", e.Time, want)
	}
}

func TestScan(t *testing.T) {
	long := strings.Repeat("a", MaxLineBytes+10)
	tests := []struct {
		name          string
		input         string
		wantEntries   int
		wantMalformed int
	}{
