			if err != nil {
				t.Fatalf("Scan error = %v, want nil", err)
			}
			if n != tc.wantEntries || mal != tc.wantMalformed {
				t.Errorf("Scan = %d entries, %d malformed; want %d, %d", n, mal, tc.wantEntries, tc.wantMalformed)
			}
		})
	}
}

type failReader struct{ err error }

func (r failReader) Read([]byte) (int, error) { return 0, r.err }

func TestScanErrors(t *testing.T) {
	boom := errors.New("boom")
	cancelled, cancel := context.WithCancel(context.Background())
	cancel()
	tests := []struct {
		name string
		ctx  context.Context
		r    failReader
		want error
	}{
		{name: "read error", ctx: context.Background(), r: failReader{boom}, want: boom},
		{name: "cancelled", ctx: cancelled, r: failReader{boom}, want: context.Canceled},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := Scan(tc.ctx, tc.r, func(Entry) {})
			if !errors.Is(err, tc.want) {
				t.Errorf("Scan error = %v, want %v", err, tc.want)
			}
		})
	}
}

