// Package stats aggregates parsed access log entries into a report.
package stats

import (
	"fmt"
	"io"
	"math"
	"sort"
	"time"

	"example.com/app/internal/logparse"
)

// Collector accumulates entries. The zero value is not ready; use NewCollector.
// A Collector is not safe for concurrent use.
type Collector struct {
	total     int
	malformed int
	paths     map[string]int
	classes   [4]int // 2xx, 3xx, 4xx, 5xx
	timesMS   []float64
	errsHour  map[time.Time]int
}

// NewCollector returns an empty Collector.
func NewCollector() *Collector {
	return &Collector{
		paths:    make(map[string]int),
		errsHour: make(map[time.Time]int),
	}
}

// Add records one valid entry.
func (c *Collector) Add(e logparse.Entry) {
	c.total++
	c.paths[e.Path]++
	if cl := e.Status/100 - 2; cl >= 0 && cl < len(c.classes) {
		c.classes[cl]++
	}
	c.timesMS = append(c.timesMS, float64(e.RequestTime)/float64(time.Millisecond))
	if e.Status >= 500 && e.Status <= 599 {
		c.errsHour[e.Time.UTC().Truncate(time.Hour)]++
	}
}

// AddMalformed records n lines that could not be parsed.
func (c *Collector) AddMalformed(n int) { c.malformed += n }

// PathCount is a request path and how often it was requested.
type PathCount struct {
	Path  string `json:"path"`
	Count int    `json:"count"`
}

// StatusClasses holds request counts per status class.
type StatusClasses struct {
	Class2xx int `json:"2xx"`
	Class3xx int `json:"3xx"`
	Class4xx int `json:"4xx"`
	Class5xx int `json:"5xx"`
}

// Percentiles holds request time percentiles in milliseconds.
type Percentiles struct {
	P50 float64 `json:"p50"`
	P95 float64 `json:"p95"`
	P99 float64 `json:"p99"`
}

// HourErrors is the number of 5xx responses in one UTC hour.
type HourErrors struct {
	Hour   string `json:"hour"` // RFC 3339, UTC, start of the hour
	Errors int    `json:"errors"`
}

// Report is the final analysis.
type Report struct {
	TotalRequests    int           `json:"total_requests"`
	MalformedLines   int           `json:"malformed_lines"`
	TopPaths         []PathCount   `json:"top_paths"`
	StatusClasses    StatusClasses `json:"status_classes"`
	RequestTimeMS    Percentiles   `json:"request_time_ms"`
	ServerErrorsHour []HourErrors  `json:"server_errors_per_hour"`
}

// Report builds the report with at most top paths. A negative top is treated
// as zero.
func (c *Collector) Report(top int) Report {
	r := Report{
		TotalRequests:    c.total,
		MalformedLines:   c.malformed,
		TopPaths:         TopN(c.paths, top),
		StatusClasses:    StatusClasses{c.classes[0], c.classes[1], c.classes[2], c.classes[3]},
		ServerErrorsHour: []HourErrors{},
	}
	sorted := append([]float64(nil), c.timesMS...)
	sort.Float64s(sorted)
	r.RequestTimeMS = Percentiles{
		P50: Percentile(sorted, 50),
		P95: Percentile(sorted, 95),
		P99: Percentile(sorted, 99),
	}
	hours := make([]time.Time, 0, len(c.errsHour))
	for h := range c.errsHour {
		hours = append(hours, h)
	}
	sort.Slice(hours, func(i, j int) bool { return hours[i].Before(hours[j]) })
	for _, h := range hours {
		r.ServerErrorsHour = append(r.ServerErrorsHour, HourErrors{
			Hour:   h.Format(time.RFC3339),
			Errors: c.errsHour[h],
		})
	}
	return r
}

// TopN returns the n most frequent keys of counts, most frequent first, ties
// broken by key. A non-positive n returns an empty, non-nil slice.
func TopN(counts map[string]int, n int) []PathCount {
	out := make([]PathCount, 0, len(counts))
	for p, k := range counts {
		out = append(out, PathCount{Path: p, Count: k})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Path < out[j].Path
	})
	if n < 0 {
		n = 0
	}
	if len(out) > n {
		out = out[:n]
	}
	return out
}

// Percentile returns the p-th percentile (0 to 100) of sorted, using the
// nearest-rank method. It returns 0 for empty input. Values of p outside
// 0 to 100 are clamped. sorted must be in ascending order.
func Percentile(sorted []float64, p float64) float64 {
	if len(sorted) == 0 || math.IsNaN(p) {
		return 0
	}
	p = math.Min(math.Max(p, 0), 100)
	rank := int(math.Ceil(p / 100 * float64(len(sorted))))
	if rank < 1 {
		rank = 1
	}
	if rank > len(sorted) {
		rank = len(sorted)
	}
	return sorted[rank-1]
}

// WriteText writes the report as a plain text table.
func (r Report) WriteText(w io.Writer) error {
	var err error
	p := func(format string, args ...any) {
		if err == nil {
			_, err = fmt.Fprintf(w, format, args...)
		}
	}
	p("Total requests:  %d\n", r.TotalRequests)
	p("Malformed lines: %d\n", r.MalformedLines)
	p("\nTop paths\n")
	for _, pc := range r.TopPaths {
		p("  %8d  %s\n", pc.Count, pc.Path)
	}
	p("\nStatus classes\n")
	p("  2xx  %d\n  3xx  %d\n  4xx  %d\n  5xx  %d\n",
		r.StatusClasses.Class2xx, r.StatusClasses.Class3xx,
		r.StatusClasses.Class4xx, r.StatusClasses.Class5xx)
	p("\nRequest time (ms)\n")
	p("  p50  %.3f\n  p95  %.3f\n  p99  %.3f\n", r.RequestTimeMS.P50, r.RequestTimeMS.P95, r.RequestTimeMS.P99)
	p("\n5xx per hour (UTC)\n")
	for _, h := range r.ServerErrorsHour {
		p("  %s  %d\n", h.Hour, h.Errors)
	}
	if err != nil {
		return fmt.Errorf("write report: %w", err)
	}
	return nil
}

